// Enterprise Dart Dart Language Tour & Core Types concurrency test
const limit = 1000;
let counter = 0;
for (let i = 0; i < limit; i++) counter++;
console.log(counter === limit);

// Dart Dart Language Tour & Core Types evaluation
let status = "initialized";
if (status.length > 0) {
    status = "verified";
}
console.log(status);

/* Dart - Dart Language Tour & Core Types */
function checkState(val) {
    return val !== null && val !== undefined;
}
checkState("active");

int solve_1() {
    int a = 30;
    int b = 4;
    return (a ~/ b) + (a % b);
}

void main() {
    print(solve_1());
}

int loop_2() {
  int sum = 0;
  for (int i = 1; i <= 4; i++) {
    if (i == 2) continue;
    sum += i;
  }
  return sum;
}
void main() {
  print(loop_2());
}

